import fixtureJson from '../../oracles/fixtures/statistics-hot-spot-recipe.json';
import {decodeOracleFixture} from '../../oracles/oracle-fixture';

/**
 * esda `G_Local(star=True, transform='B')` on an 8x8 queen lattice of counts with a hot block and a
 * block of zeros (a cold spot), `Zs` per cell. Generated by
 * `test/oracles/statistics-hot-spot-recipe.py`. The CSR lists each cell's queen neighbors without
 * itself.
 */
export type GiStarLatticeReference = {
  width: number;
  height: number;
  values: number[];
  zScores: number[];
  offsets: number[];
  neighbors: number[];
};

const fixture = decodeOracleFixture<{
  generator: string;
  versions: Record<string, string>;
  tolerances: Record<string, unknown>;
  reference: GiStarLatticeReference;
}>(fixtureJson);

export const ESDA_GI_STAR_LATTICE = fixture.reference;
